import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getRazorpayCredentials } from "../_shared/credentials.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

function parseNotesOrderIds(notes: any): string[] {
  if (!notes) return [];
  if (notes.order_ids) {
    try {
      const parsed = typeof notes.order_ids === "string" ? JSON.parse(notes.order_ids) : notes.order_ids;
      if (Array.isArray(parsed)) return parsed.map(String);
    } catch { /* fall through */ }
  }
  if (notes.order_id) return [String(notes.order_id)];
  return [];
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // Auth: JWT buyer OR service-role (webhook/cron)
    const authHeader = req.headers.get("Authorization") || "";
    const isService = authHeader === `Bearer ${supabaseServiceKey}`;
    let callerUserId: string | null = null;

    if (!isService) {
      const { withAuth } = await import("../_shared/auth.ts");
      const authResult = await withAuth(req, corsHeaders);
      if (authResult instanceof Response) return authResult;
      callerUserId = authResult.userId;
    }

    const body = await req.json().catch(() => null);
    if (!body) {
      return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { razorpay_payment_id, razorpay_order_id } = body;
    let order_ids: string[] = Array.isArray(body.order_ids) ? body.order_ids.map(String) : [];
    const source = body.source || (isService ? "service" : "client_confirm");

    if (
      (!razorpay_payment_id && !razorpay_order_id) ||
      !order_ids ||
      order_ids.length === 0
    ) {
      return new Response(
        JSON.stringify({ error: "Missing razorpay_payment_id/razorpay_order_id or order_ids" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const creds = await getRazorpayCredentials(supabase);
    if (!creds.keyId || !creds.keySecret) {
      return new Response(JSON.stringify({ error: "Payment gateway not configured" }), {
        status: 503,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const authBasic = "Basic " + btoa(`${creds.keyId}:${creds.keySecret}`);

    // Load seed orders, then expand ALL siblings via checkout_group_id BEFORE amount check
    const { data: seedOrders, error: seedErr } = await supabase
      .from("orders")
      .select("id, buyer_id, seller_id, total_amount, society_id, status, payment_status, razorpay_order_id, platform_fee, net_amount, loyalty_reservation_id, loyalty_discount_amount, loyalty_points_redeemed, checkout_group_id")
      .in("id", order_ids);

    if (seedErr || !seedOrders || seedOrders.length === 0) {
      return new Response(JSON.stringify({ error: "One or more orders not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const groupIds = Array.from(
      new Set(
        seedOrders
          .map((o: any) => o.checkout_group_id)
          .filter((id: string | null | undefined) => !!id),
      ),
    ) as string[];

    let orders = seedOrders as any[];
    if (groupIds.length > 0) {
      const { data: siblings, error: sibErr } = await supabase
        .from("orders")
        .select("id, buyer_id, seller_id, total_amount, society_id, status, payment_status, razorpay_order_id, platform_fee, net_amount, loyalty_reservation_id, loyalty_discount_amount, loyalty_points_redeemed, checkout_group_id")
        .in("checkout_group_id", groupIds);

      if (sibErr || !siblings?.length) {
        return new Response(JSON.stringify({ error: "Failed to resolve checkout group siblings" }), {
          status: 500,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      orders = siblings;
      order_ids = siblings.map((o: any) => o.id);
      console.log(`[confirm] expanded checkout_group siblings → ${order_ids.length} orders`, groupIds);
    } else if (seedOrders.length !== order_ids.length) {
      return new Response(JSON.stringify({ error: "One or more orders not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (callerUserId) {
      const unauthorized = orders.some((o: any) => o.buyer_id !== callerUserId);
      if (unauthorized) {
        return new Response(JSON.stringify({ error: "Forbidden" }), {
          status: 403,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
    }

    const expectedPaise = Math.round(
      orders.reduce((sum: number, o: any) => sum + Number(o.total_amount || 0), 0) * 100
    );
    const expectedRzpOrderId = orders[0]?.razorpay_order_id || razorpay_order_id;

    let verifiedPaymentId = razorpay_payment_id;
    let paymentEntity: any = null;

    if (razorpay_payment_id && razorpay_payment_id !== "reconciled") {
      const rzpResponse = await fetch(
        `https://api.razorpay.com/v1/payments/${razorpay_payment_id}`,
        { headers: { Authorization: authBasic } }
      );
      if (!rzpResponse.ok) {
        return new Response(JSON.stringify({ error: "Payment verification failed" }), {
          status: 502,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      paymentEntity = await rzpResponse.json();
      if (paymentEntity.status !== "captured" && paymentEntity.status !== "authorized") {
        return new Response(
          JSON.stringify({ error: "Payment not confirmed", status: paymentEntity.status }),
          { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
    } else if (expectedRzpOrderId) {
      const rzpResponse = await fetch(
        `https://api.razorpay.com/v1/orders/${expectedRzpOrderId}/payments`,
        { headers: { Authorization: authBasic } }
      );
      if (!rzpResponse.ok) {
        return new Response(JSON.stringify({ error: "Payment verification failed" }), {
          status: 502,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      const data = await rzpResponse.json();
      const items = data.items || data;
      paymentEntity = Array.isArray(items)
        ? items.find((p: any) => p.status === "captured" || p.status === "authorized")
        : null;
      if (!paymentEntity) {
        return new Response(
          JSON.stringify({ error: "No captured payment found for this order" }),
          { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
      verifiedPaymentId = paymentEntity.id;
    } else {
      return new Response(JSON.stringify({ error: "Cannot verify payment without ID" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Amount binding against FULL sibling set (allow 1 paise rounding)
    const paidPaise = Number(paymentEntity.amount || 0);
    if (Math.abs(paidPaise - expectedPaise) > 1) {
      console.error(`[confirm] amount mismatch paid=${paidPaise} expected=${expectedPaise} orders=${order_ids.length}`);
      return new Response(
        JSON.stringify({ error: "Payment amount does not match order total" }),
        { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Bind Razorpay order id when present on payment
    if (paymentEntity.order_id && expectedRzpOrderId && paymentEntity.order_id !== expectedRzpOrderId) {
      console.error(`[confirm] razorpay_order_id mismatch`);
      return new Response(
        JSON.stringify({ error: "Payment does not belong to these orders" }),
        { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Bind notes order_ids when present
    const noteIds = parseNotesOrderIds(paymentEntity.notes);
    if (noteIds.length > 0) {
      const missingFromNotes = order_ids.filter((id: string) => !noteIds.includes(id));
      if (missingFromNotes.length > 0) {
        return new Response(
          JSON.stringify({
            error: "Payment notes do not include all checkout group orders",
            missing: missingFromNotes,
          }),
          { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
    }

    // ONE DB transaction: payment_records + orders + group stamp + loyalty/wallet
    const { data: commitData, error: commitErr } = await supabase.rpc(
      "confirm_orders_after_razorpay_payment",
      {
        p_order_ids: order_ids,
        p_razorpay_payment_id: verifiedPaymentId,
        p_razorpay_order_id: expectedRzpOrderId || razorpay_order_id || null,
        p_source: source,
      },
    );

    if (commitErr) {
      console.error("[confirm] atomic commit failed", commitErr);
      return new Response(
        JSON.stringify({
          success: false,
          error: commitErr.message || "atomic_confirm_failed",
          source,
          order_ids,
        }),
        { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const allOk = commitData?.success === true;
    const successCount = Number(commitData?.confirmed || 0);

    if (allOk && successCount > 0) {
      setTimeout(() => {
        fetch(`${supabaseUrl}/functions/v1/process-notification-queue`, {
          method: "POST",
          headers: {
            Authorization: `Bearer ${supabaseServiceKey}`,
            "Content-Type": "application/json",
          },
          body: "{}",
        }).catch(() => {});
      }, 2000);
    }

    return new Response(
      JSON.stringify({
        success: allOk,
        confirmed: successCount,
        results: commitData?.results || [],
        loyalty: commitData?.loyalty,
        wallet: commitData?.wallet,
        commit_failed: !allOk,
        atomic: true,
        source,
        order_ids: commitData?.order_ids || order_ids,
      }),
      { status: allOk ? 200 : 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("confirm-razorpay-payment error:", error);
    return new Response(JSON.stringify({ error: String(error) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

/**
 * Credential resolution order (Phase 0 residual closeout):
 * 1) Deno.env / platform secrets
 * 2) Vault via get_edge_credential RPC (falls back to admin_settings server-side)
 *
 * Never prefer admin_settings SELECT from the edge. Authenticated admin UI must
 * use get_admin_credential_meta (meta-only — no raw secrets).
 */
export async function getCredential(
  supabase: any,
  dbKey: string,
  envKey: string
): Promise<string | undefined> {
  const fromEnv = Deno.env.get(envKey);
  if (fromEnv && fromEnv.trim().length > 0) return fromEnv;

  try {
    const { data, error } = await supabase.rpc("get_edge_credential", {
      p_key: dbKey,
    });
    if (!error && typeof data === "string" && data.trim().length > 0) {
      return data;
    }
    if (error) {
      console.warn(`get_edge_credential failed for ${dbKey}:`, error.message || error);
    }
  } catch (e) {
    console.warn(`get_edge_credential exception for ${dbKey}:`, e);
  }

  return undefined;
}

/** Razorpay key pair — env first, then vault/DB via RPC */
export async function getRazorpayCredentials(supabase: any): Promise<{
  keyId: string;
  keySecret: string;
}> {
  const keyId =
    (await getCredential(supabase, "razorpay_key_id", "RAZORPAY_KEY_ID")) || "";
  const keySecret =
    (await getCredential(supabase, "razorpay_key_secret", "RAZORPAY_KEY_SECRET")) ||
    "";
  return { keyId, keySecret };
}

export async function getRazorpayWebhookSecret(
  supabase: any
): Promise<string | null> {
  const secret = await getCredential(
    supabase,
    "razorpay_webhook_secret",
    "RAZORPAY_WEBHOOK_SECRET"
  );
  return secret && secret.trim().length > 0 ? secret : null;
}

/** Create a service-role Supabase client for credential lookups */
export function createAdminClient() {
  return createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

/**
 * Shared auth middleware for edge functions.
 * Extracts and validates Bearer token, returns userId and userClient.
 *
 * Usage:
 *   const authResult = await withAuth(req, corsHeaders);
 *   if (authResult instanceof Response) return authResult;
 *   const { userId, userClient } = authResult;
 */
export async function withAuth(
  req: Request,
  corsHeaders: Record<string, string>
): Promise<{ userId: string; userClient: ReturnType<typeof createClient> } | Response> {
  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const userClient = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_ANON_KEY")!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data: { user }, error } = await userClient.auth.getUser();
  if (error || !user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  return { userId: user.id, userClient };
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { checkRateLimit, rateLimitResponse } from "../_shared/rate-limiter.ts";
import { getRazorpayCredentials } from "../_shared/credentials.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface CreateOrderRequest {
  orderId?: string;
  orderIds?: string[];
  amount?: number;
  sellerId: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
}

async function getRazorpayKeys(supabase: any): Promise<{ keyId: string; keySecret: string } | null> {
  const keys = await getRazorpayCredentials(supabase);
  if (!keys.keyId || !keys.keySecret) return null;
  return keys;
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const razorpayKeys = await getRazorpayKeys(supabase);
    if (!razorpayKeys) {
      console.error('Razorpay keys not configured');
      return new Response(
        JSON.stringify({ error: 'Payment gateway not configured. Please contact admin.' }),
        { status: 503, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const { withAuth } = await import("../_shared/auth.ts");
    const authResult = await withAuth(req, corsHeaders);
    if (authResult instanceof Response) return authResult;
    const user = { id: authResult.userId };

    const { allowed } = await checkRateLimit(`order:${user.id}`, 10, 60);
    if (!allowed) return rateLimitResponse(corsHeaders);

    const body: CreateOrderRequest = await req.json();
    const { sellerId, customerName, customerEmail, customerPhone } = body;
    const clientAmount = body.amount;

    const allOrderIds: string[] = body.orderIds?.length ? body.orderIds : (body.orderId ? [body.orderId] : []);
    if (allOrderIds.length === 0) {
      return new Response(
        JSON.stringify({ error: 'No order IDs provided' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Validate ALL orders belong to buyer, are not cancelled, and have payment_status: 'pending'
    const { data: orders, error: orderError } = await supabase
      .from('orders')
      .select('id, buyer_id, seller_id, status, payment_status, razorpay_order_id, total_amount, checkout_group_id')
      .in('id', allOrderIds)
      .eq('buyer_id', user.id)
      .neq('status', 'cancelled')
      .eq('payment_status', 'pending');

    if (orderError || !orders || orders.length !== allOrderIds.length) {
      const foundIds = orders?.map((o: any) => o.id) || [];
      const missing = allOrderIds.filter(id => !foundIds.includes(id));
      console.error('Order validation failed. Expected:', allOrderIds.length, 'Found:', orders?.length, 'Missing:', missing);
      return new Response(
        JSON.stringify({ error: 'One or more orders not found, already cancelled, or already paid' }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const uniqueSellers = new Set(orders.map((o: any) => o.seller_id).filter(Boolean));
    const isMultiSeller = uniqueSellers.size > 1;

    // P5: multi-seller online is platform-collect (one Razorpay payment → N child orders).
    // Route transfers only for single-seller + linked account (below).
    const resolvedSellerId = [...uniqueSellers][0] as string | undefined;
    if (!resolvedSellerId) {
      return new Response(
        JSON.stringify({ error: 'Order is missing seller_id' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
    if (!isMultiSeller && sellerId && sellerId !== resolvedSellerId) {
      console.warn('Client sellerId mismatch; using order seller_id', { sellerId, resolvedSellerId });
    }

    // Amount from DB only — never trust client-supplied amount
    const dbAmount = orders.reduce((sum: number, o: any) => sum + Number(o.total_amount || 0), 0);
    if (dbAmount <= 0) {
      return new Response(
        JSON.stringify({ error: 'Invalid order total' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
    if (typeof clientAmount === 'number' && Math.abs(clientAmount - dbAmount) > 0.5) {
      console.warn('[create-razorpay-order] client amount ignored', { client: clientAmount, db: dbAmount });
    }

    console.log('Creating Razorpay order for orders:', allOrderIds, 'amount:', dbAmount, 'sellerId:', resolvedSellerId);

    // Multi-order checkout = platform collect once (merchant of record).
    // Route `transfers` only for a single order with linked seller account below.

    // Idempotency: reuse existing Razorpay order if still valid
    const existingRzpId = orders[0]?.razorpay_order_id;
    const razorpayAuth = btoa(`${razorpayKeys.keyId}:${razorpayKeys.keySecret}`);
    if (existingRzpId) {
      try {
        const fetchRes = await fetch(`https://api.razorpay.com/v1/orders/${existingRzpId}`, {
          headers: { 'Authorization': `Basic ${razorpayAuth}` },
        });
        if (fetchRes.ok) {
          const existingOrder = await fetchRes.json();
          const existingPaise = Number(existingOrder.amount || 0);
          const expectedPaise = Math.round(dbAmount * 100);
          if (
            (existingOrder.status === 'created' || existingOrder.status === 'attempted') &&
            Math.abs(existingPaise - expectedPaise) <= 1
          ) {
            console.log('Reusing existing Razorpay order:', existingRzpId, 'status:', existingOrder.status);
            return new Response(
              JSON.stringify({
                razorpay_order_id: existingOrder.id,
                razorpay_key_id: razorpayKeys.keyId,
                amount: existingOrder.amount,
                currency: existingOrder.currency,
                prefill: { name: customerName, email: customerEmail, contact: customerPhone },
                notes: existingOrder.notes,
                reused: true,
              }),
              { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
            );
          }
          console.log('Existing Razorpay order', existingRzpId, 'not reusable — creating new one');
        }
      } catch (e) {
        console.warn('Failed to fetch existing Razorpay order, creating new one:', e);
      }
    }

    const checkoutGroupId =
      orders.map((o: any) => o.checkout_group_id).find((id: string | null) => !!id) || null;

    const { data: seller } = !isMultiSeller
      ? await supabase
          .from('seller_profiles')
          .select('razorpay_account_id, business_name')
          .eq('id', resolvedSellerId)
          .single()
      : { data: null };

    const amountPaise = Math.round(dbAmount * 100);
    const orderPayload: any = {
      amount: amountPaise,
      currency: 'INR',
      receipt: allOrderIds[0].slice(0, 40),
      notes: {
        order_id: allOrderIds[0],
        order_ids: JSON.stringify(allOrderIds),
        seller_id: isMultiSeller ? 'multi' : resolvedSellerId,
        seller_ids: JSON.stringify([...uniqueSellers]),
        buyer_id: user.id,
        checkout_group_id: checkoutGroupId || '',
        platform_collect: isMultiSeller || allOrderIds.length > 1 ? '1' : '0',
      },
    };

    // Route transfers only for single-order single-seller with linked account.
    // Multi-seller / multi-order = platform collect (partial refunds per child in P4).
    if (!isMultiSeller && allOrderIds.length === 1 && seller?.razorpay_account_id) {
      orderPayload.transfers = [
        {
          account: seller.razorpay_account_id,
          amount: amountPaise,
          currency: 'INR',
          notes: { order_id: allOrderIds[0], type: 'seller_payout' },
          on_hold: 0,
        },
      ];
    }

    console.log('Razorpay order payload:', orderPayload);

    const razorpayResponse = await fetch('https://api.razorpay.com/v1/orders', {
      method: 'POST',
      headers: {
        'Authorization': `Basic ${razorpayAuth}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(orderPayload),
    });

    if (!razorpayResponse.ok) {
      const errorText = await razorpayResponse.text();
      console.error('Razorpay error:', errorText);
      return new Response(
        JSON.stringify({ error: 'Failed to create payment order', details: errorText }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const razorpayOrder = await razorpayResponse.json();
    console.log('Razorpay order created:', razorpayOrder.id, 'for', allOrderIds.length, 'orders');

    for (const oid of allOrderIds) {
      const { error: linkErr } = await supabase
        .from('orders')
        .update({ razorpay_order_id: razorpayOrder.id })
        .eq('id', oid);
      if (linkErr) {
        console.error('Failed to link razorpay_order_id on order', oid, linkErr);
        return new Response(
          JSON.stringify({ error: 'Payment order created but failed to link to Sociva order', details: linkErr.message }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }
    }

    if (checkoutGroupId) {
      const { error: groupLinkErr } = await supabase
        .from('checkout_groups')
        .update({
          razorpay_order_id: razorpayOrder.id,
          payment_method: 'online',
          updated_at: new Date().toISOString(),
        })
        .eq('id', checkoutGroupId);
      if (groupLinkErr) {
        console.warn('Failed to link razorpay_order_id on checkout_group', checkoutGroupId, groupLinkErr);
      }
    }

    return new Response(
      JSON.stringify({
        razorpay_order_id: razorpayOrder.id,
        razorpay_key_id: razorpayKeys.keyId,
        amount: razorpayOrder.amount,
        currency: razorpayOrder.currency,
        prefill: { name: customerName, email: customerEmail, contact: customerPhone },
        notes: razorpayOrder.notes,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error: unknown) {
    console.error('Error creating order:', error);
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return new Response(
      JSON.stringify({ error: 'Internal server error', details: errorMessage }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
