// Refund Processor Edge Function
// Executes real Razorpay refunds — never simulates success.
// P4: partial refunds against shared checkout-group captures.
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";
import { getRazorpayCredentials } from "../_shared/credentials.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

interface ProcessRequest {
  refund_id: string;
}

async function getRazorpayKeys(supabase: any): Promise<{ keyId: string; keySecret: string } | null> {
  const keys = await getRazorpayCredentials(supabase);
  if (!keys.keyId || !keys.keySecret) return null;
  return keys;
}

async function fetchPaymentRefundable(
  keys: { keyId: string; keySecret: string },
  paymentId: string,
): Promise<{ amountPaise: number; amountRefundedPaise: number; status: string } | null> {
  const auth = "Basic " + btoa(`${keys.keyId}:${keys.keySecret}`);
  const res = await fetch(`https://api.razorpay.com/v1/payments/${paymentId}`, {
    headers: { Authorization: auth },
  });
  const raw = await res.json().catch(() => ({}));
  if (!res.ok) {
    console.error("[refund-processor] payment fetch failed", paymentId, raw);
    return null;
  }
  return {
    amountPaise: Number(raw.amount || 0),
    amountRefundedPaise: Number(raw.amount_refunded || 0),
    status: String(raw.status || ""),
  };
}

async function callRazorpayRefund(
  keys: { keyId: string; keySecret: string },
  paymentId: string,
  amountRupees: number,
  refundId: string,
  opts?: { reverseAll?: boolean },
): Promise<{ ok: boolean; reference: string; status: string; raw: any; error?: string }> {
  const amountPaise = Math.round(Number(amountRupees) * 100);
  const auth = "Basic " + btoa(`${keys.keyId}:${keys.keySecret}`);

  const body: Record<string, unknown> = {
    amount: amountPaise,
    notes: { refund_request_id: refundId, sociva_partial: true },
  };
  // Route: reverse linked transfers when this refund covers the full remaining capture
  if (opts?.reverseAll) {
    body.reverse_all = 1;
  }

  const res = await fetch(`https://api.razorpay.com/v1/payments/${paymentId}/refund`, {
    method: "POST",
    headers: {
      Authorization: auth,
      "Content-Type": "application/json",
      "X-Razorpay-Idempotency-Key": `refund-${refundId}`,
    },
    body: JSON.stringify(body),
  });

  const raw = await res.json().catch(() => ({}));
  if (!res.ok) {
    return {
      ok: false,
      reference: "",
      status: "failed",
      raw,
      error: raw?.error?.description || raw?.error?.reason || `HTTP ${res.status}`,
    };
  }

  return {
    ok: true,
    reference: raw.id || `rzp_rfnd_${refundId.slice(0, 8)}`,
    status: raw.status || "processed",
    raw,
  };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, serviceKey);

    const authHeader = req.headers.get("Authorization") || "";
    const isService = authHeader === `Bearer ${serviceKey}`;
    const isCron = req.headers.get("x-cron-secret") === Deno.env.get("CRON_SECRET");
    let callerUserId: string | null = null;

    if (!isService && !isCron) {
      const userClient = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY")!, {
        global: { headers: { Authorization: authHeader } },
      });
      const { data: { user } } = await userClient.auth.getUser();
      if (!user) {
        return new Response(JSON.stringify({ error: "Unauthorized" }), {
          status: 401,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      callerUserId = user.id;
    }

    const body = (await req.json().catch(() => ({}))) as ProcessRequest;
    if (!body.refund_id) {
      return new Response(JSON.stringify({ error: "refund_id required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { data: refund, error: fetchErr } = await supabase
      .from("refund_requests")
      .select("id, refund_state, amount, order_id, buyer_id, refund_destination, wallet_credit_amount")
      .eq("id", body.refund_id)
      .single();

    if (fetchErr || !refund) {
      return new Response(JSON.stringify({ error: "Refund not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Ownership: seller of order, admin, or service/cron
    if (callerUserId) {
      const { data: order } = await supabase
        .from("orders")
        .select("seller_id")
        .eq("id", refund.order_id)
        .single();

      const { data: sellerProfile } = order?.seller_id
        ? await supabase
            .from("seller_profiles")
            .select("user_id")
            .eq("id", order.seller_id)
            .maybeSingle()
        : { data: null };

      const { data: isAdmin } = await supabase.rpc("is_admin", { _user_id: callerUserId });
      const isSellerOwner = sellerProfile?.user_id === callerUserId;

      if (!isSellerOwner && !isAdmin) {
        return new Response(JSON.stringify({ error: "Forbidden" }), {
          status: 403,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
    }

    if (refund.refund_state === "refund_completed" || refund.refund_state === "settled") {
      return new Response(
        JSON.stringify({
          ok: true,
          skipped: true,
          state: refund.refund_state,
          message: `Refund already completed`,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    if (refund.refund_state !== "approved") {
      return new Response(
        JSON.stringify({
          ok: true,
          skipped: true,
          state: refund.refund_state,
          message: `Refund already in state ${refund.refund_state}`,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // Sociva Credit path: skip Razorpay, credit wallet + complete
    const destination = (refund as { refund_destination?: string }).refund_destination || "original_payment";
    if (destination === "wallet") {
      const { data: walletDone, error: walletErr } = await supabase.rpc("complete_wallet_refund", {
        p_refund_id: refund.id,
      });
      if (walletErr) {
        console.error("[refund-processor] wallet refund failed", walletErr);
        await supabase.rpc("fail_refund", {
          p_refund_id: refund.id,
          p_reason: walletErr.message || "Wallet credit failed",
        });
        return new Response(
          JSON.stringify({ ok: false, state: "refund_failed", error: walletErr.message, destination: "wallet" }),
          { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
        );
      }
      console.log(`[refund-processor] completed wallet refund ${refund.id}`);
      return new Response(
        JSON.stringify({
          ok: true,
          state: "refund_completed",
          destination: "wallet",
          gateway_ref: walletDone?.gateway_refund_id || null,
          simulated: false,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const keys = await getRazorpayKeys(supabase);
    if (!keys) {
      return new Response(
        JSON.stringify({
          error: "Refund gateway not configured. Set Razorpay keys before processing refunds.",
        }),
        { status: 503, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // P4: resolve payment from order OR checkout_group; amount = child share
    const { data: gwCtx, error: ctxErr } = await supabase.rpc("resolve_refund_gateway_context", {
      p_refund_id: refund.id,
    });
    if (ctxErr) {
      console.error("[refund-processor] resolve context failed", ctxErr);
    }
    const ctx = (gwCtx || {}) as {
      ok?: boolean;
      razorpay_payment_id?: string;
      amount?: number;
      is_partial?: boolean;
      checkout_group_id?: string;
    };

    let paymentId = ctx.razorpay_payment_id || null;
    if (!paymentId) {
      const { data: orderPay } = await supabase
        .from("orders")
        .select("razorpay_payment_id, checkout_group_id")
        .eq("id", refund.order_id)
        .single();
      paymentId = orderPay?.razorpay_payment_id || null;
      if (!paymentId && orderPay?.checkout_group_id) {
        const { data: group } = await supabase
          .from("checkout_groups")
          .select("razorpay_payment_id")
          .eq("id", orderPay.checkout_group_id)
          .maybeSingle();
        paymentId = group?.razorpay_payment_id || null;
      }
    }

    if (!paymentId) {
      // Audit: no razorpay_payment_id → route to wallet destination
      console.warn(`[refund-processor] no razorpay_payment_id for ${refund.id} — routing to wallet`);
      await supabase
        .from("refund_requests")
        .update({
          refund_destination: "wallet",
          wallet_credit_amount: refund.amount,
          updated_at: new Date().toISOString(),
        })
        .eq("id", refund.id)
        .eq("refund_state", "approved");

      const { data: walletDone, error: walletErr } = await supabase.rpc("complete_wallet_refund", {
        p_refund_id: refund.id,
      });
      if (walletErr) {
        console.error("[refund-processor] wallet fallback failed", walletErr);
        await supabase.rpc("fail_refund", {
          p_refund_id: refund.id,
          p_reason: walletErr.message || "Wallet credit failed (no razorpay_payment_id)",
        });
        return new Response(
          JSON.stringify({ ok: false, state: "refund_failed", error: walletErr.message, destination: "wallet" }),
          { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
        );
      }
      return new Response(
        JSON.stringify({
          ok: true,
          state: "refund_completed",
          destination: "wallet",
          gateway_ref: walletDone?.gateway_refund_id || null,
          routed_from: "missing_razorpay_payment_id",
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const idempotencyKey = `refund-${refund.id}-attempt-1`;
    const { error: initErr } = await supabase.rpc("initiate_refund", {
      p_refund_id: refund.id,
      p_idempotency_key: idempotencyKey,
    });
    if (initErr) {
      console.error("[refund-processor] initiate failed", initErr);
      return new Response(JSON.stringify({ error: initErr.message }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // P0: ignore client-stored refund.amount — recompute from order server-side only
    let gatewayRefundAmount = Number(ctx.amount);
    if (!Number.isFinite(gatewayRefundAmount) || gatewayRefundAmount <= 0) {
      const { data: recomputed } = await supabase.rpc("compute_child_gateway_refund_amount", {
        _order_id: refund.order_id,
      });
      gatewayRefundAmount = Number(recomputed);
    }
    if (!Number.isFinite(gatewayRefundAmount) || gatewayRefundAmount <= 0) {
      await supabase.rpc("fail_refund", {
        p_refund_id: refund.id,
        p_reason: "Server could not compute refund amount from order",
      });
      return new Response(
        JSON.stringify({ ok: false, state: "refund_failed", error: "uncomputable_refund_amount" }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // Cap against live Razorpay remaining (partial refunds must not overshoot)
    const live = await fetchPaymentRefundable(keys, paymentId);
    if (live) {
      const remainingRupees = Math.max(0, (live.amountPaise - live.amountRefundedPaise) / 100);
      if (remainingRupees <= 0) {
        // Already fully refunded at gateway — complete locally idempotently
        const { error: doneErr } = await supabase.rpc("complete_refund", {
          p_refund_id: refund.id,
          p_gateway_ref: `already-refunded-${paymentId}`,
          p_gateway_status: "already_refunded",
        });
        if (doneErr) {
          console.error("[refund-processor] complete after already-refunded failed", doneErr);
          return new Response(JSON.stringify({ error: doneErr.message }), {
            status: 500,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          });
        }
        return new Response(
          JSON.stringify({
            ok: true,
            state: "refund_completed",
            gateway_ref: `already-refunded-${paymentId}`,
            simulated: false,
            note: "payment already fully refunded at gateway",
          }),
          { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
        );
      }
      gatewayRefundAmount = Math.min(gatewayRefundAmount, remainingRupees);
    }

    // Round to paise-safe 2dp
    gatewayRefundAmount = Math.round(gatewayRefundAmount * 100) / 100;
    if (gatewayRefundAmount < 0.01) {
      await supabase.rpc("fail_refund", {
        p_refund_id: refund.id,
        p_reason: "Computed gateway refund amount is zero",
      });
      return new Response(
        JSON.stringify({ ok: false, state: "refund_failed", error: "zero_refund_amount" }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const remainingAfter = live
      ? (live.amountPaise - live.amountRefundedPaise) / 100 - gatewayRefundAmount
      : null;
    const reverseAll = remainingAfter !== null && remainingAfter < 0.01;

    const gw = await callRazorpayRefund(keys, paymentId, gatewayRefundAmount, refund.id, {
      reverseAll,
    });

    if (gw.ok) {
      const { error: doneErr } = await supabase.rpc("complete_refund", {
        p_refund_id: refund.id,
        p_gateway_ref: gw.reference,
        p_gateway_status: gw.status,
      });
      if (doneErr) {
        console.error("[refund-processor] complete failed", doneErr);
        return new Response(JSON.stringify({ error: doneErr.message }), {
          status: 500,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      console.log(
        `[refund-processor] completed refund ${refund.id} ref=${gw.reference} amount=${gatewayRefundAmount} partial=${ctx.is_partial} reverse_all=${reverseAll}`,
      );
      return new Response(
        JSON.stringify({
          ok: true,
          state: "refund_completed",
          gateway_ref: gw.reference,
          amount: gatewayRefundAmount,
          partial: !!ctx.is_partial,
          reverse_all: reverseAll,
          simulated: false,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    await supabase.rpc("fail_refund", {
      p_refund_id: refund.id,
      p_reason: gw.error || "Gateway error",
    });
    return new Response(
      JSON.stringify({ ok: false, state: "refund_failed", error: gw.error, simulated: false }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (err: any) {
    console.error("[refund-processor] error", err);
    return new Response(JSON.stringify({ error: err.message || "Internal error" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

/**
 * Credential resolution order (Phase 0 residual closeout):
 * 1) Deno.env / platform secrets
 * 2) Vault via get_edge_credential RPC (falls back to admin_settings server-side)
 *
 * Never prefer admin_settings SELECT from the edge. Authenticated admin UI must
 * use get_admin_credential_meta (meta-only — no raw secrets).
 */
export async function getCredential(
  supabase: any,
  dbKey: string,
  envKey: string
): Promise<string | undefined> {
  const fromEnv = Deno.env.get(envKey);
  if (fromEnv && fromEnv.trim().length > 0) return fromEnv;

  try {
    const { data, error } = await supabase.rpc("get_edge_credential", {
      p_key: dbKey,
    });
    if (!error && typeof data === "string" && data.trim().length > 0) {
      return data;
    }
    if (error) {
      console.warn(`get_edge_credential failed for ${dbKey}:`, error.message || error);
    }
  } catch (e) {
    console.warn(`get_edge_credential exception for ${dbKey}:`, e);
  }

  return undefined;
}

/** Razorpay key pair — env first, then vault/DB via RPC */
export async function getRazorpayCredentials(supabase: any): Promise<{
  keyId: string;
  keySecret: string;
}> {
  const keyId =
    (await getCredential(supabase, "razorpay_key_id", "RAZORPAY_KEY_ID")) || "";
  const keySecret =
    (await getCredential(supabase, "razorpay_key_secret", "RAZORPAY_KEY_SECRET")) ||
    "";
  return { keyId, keySecret };
}

export async function getRazorpayWebhookSecret(
  supabase: any
): Promise<string | null> {
  const secret = await getCredential(
    supabase,
    "razorpay_webhook_secret",
    "RAZORPAY_WEBHOOK_SECRET"
  );
  return secret && secret.trim().length > 0 ? secret : null;
}

/** Create a service-role Supabase client for credential lookups */
export function createAdminClient() {
  return createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";
import { getRazorpayCredentials, getCredential } from "../_shared/credentials.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

/**
 * Create a Razorpay Route transfer to a linked account.
 * Returns transfer id on success.
 */
async function createRouteTransfer(opts: {
  keyId: string;
  keySecret: string;
  accountId: string;
  amountPaise: number;
  settlementId: string;
  orderId: string;
}): Promise<{ ok: true; transferId: string } | { ok: false; error: string }> {
  const authBasic = "Basic " + btoa(`${opts.keyId}:${opts.keySecret}`);
  const res = await fetch("https://api.razorpay.com/v1/transfers", {
    method: "POST",
    headers: {
      Authorization: authBasic,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      account: opts.accountId,
      amount: opts.amountPaise,
      currency: "INR",
      notes: {
        settlement_id: opts.settlementId,
        order_id: opts.orderId,
        source: "sociva_process_settlements",
      },
    }),
  });

  const body = await res.json().catch(() => ({}));
  if (!res.ok) {
    const msg =
      body?.error?.description ||
      body?.error?.reason ||
      `razorpay_transfer_http_${res.status}`;
    return { ok: false, error: String(msg) };
  }

  const transferId = body?.id;
  if (!transferId) {
    return { ok: false, error: "razorpay_transfer_missing_id" };
  }
  return { ok: true, transferId: String(transferId) };
}

/**
 * Settlement eligibility + optional Razorpay Route payout cron.
 *
 * HONESTY CONTRACT:
 * - pending → eligible after cooldown/delivery/payment checks (always).
 * - eligible → settled ONLY when route is enabled AND a real transfer id
 *   is returned from Razorpay (seller must have razorpay_account_id).
 * - Never marks settled without razorpay_transfer_id.
 */
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const authHeader = req.headers.get("Authorization");
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    if (!authHeader || authHeader !== `Bearer ${serviceRoleKey}`) {
      return new Response(
        JSON.stringify({ error: "Unauthorized — service role required" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      serviceRoleKey,
    );

    const { data: autoSetting } = await supabase
      .from("system_settings")
      .select("value")
      .eq("key", "auto_settle_enabled")
      .single();

    const autoEnabled = autoSetting?.value === "true";

    let force = false;
    try {
      const body = await req.json();
      force = body?.force === true;
    } catch {
      // No body is fine
    }

    if (!autoEnabled && !force) {
      return new Response(
        JSON.stringify({
          processed: 0,
          message: "Auto-settle is disabled. Pass force=true to override.",
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const routeVal = await getCredential(
      supabase,
      "razorpay_route_enabled",
      "RAZORPAY_ROUTE_ENABLED",
    );
    const routeEnabled = String(routeVal || "").toLowerCase() === "true";

    const creds = routeEnabled
      ? await getRazorpayCredentials(supabase)
      : { keyId: "", keySecret: "" };

    // 1) Promote pending → eligible
    const { data: pendingSettlements, error: fetchErr } = await supabase
      .from("seller_settlements")
      .select("id, order_id, seller_id, net_amount, settlement_status")
      .eq("settlement_status", "pending")
      .lte("eligible_at", new Date().toISOString());

    if (fetchErr) throw fetchErr;

    let processed = 0;
    const errors: { id: string; error: string }[] = [];
    let transferred = 0;

    const { data: allTerminalRows } = await supabase
      .from("category_status_flows")
      .select("status_key, transaction_type")
      .eq("is_terminal", true)
      .eq("is_success", true);

    const terminalByWorkflow = new Map<string, Set<string>>();
    const allTerminalStatuses = new Set<string>();
    for (const r of allTerminalRows || []) {
      allTerminalStatuses.add(r.status_key);
      if (!terminalByWorkflow.has(r.transaction_type)) {
        terminalByWorkflow.set(r.transaction_type, new Set());
      }
      terminalByWorkflow.get(r.transaction_type)!.add(r.status_key);
    }

    for (const settlement of pendingSettlements || []) {
      const { data: orderData } = await supabase
        .from("orders")
        .select(
          "status, fulfillment_type, delivery_handled_by, order_type, transaction_type, payment_status",
        )
        .eq("id", settlement.order_id)
        .single();

      const orderPay = String(orderData?.payment_status || "");
      if (["refunded", "refund_initiated", "refund_processing"].includes(orderPay)) {
        await supabase
          .from("seller_settlements")
          .update({
            settlement_status: "on_hold",
            hold_reason: `Blocked: order payment_status=${orderPay}`,
            eligible_at: null,
            updated_at: new Date().toISOString(),
          })
          .eq("id", settlement.id)
          .in("settlement_status", ["pending", "eligible", "processing"]);
        errors.push({ id: settlement.id, error: `Order ${orderPay} — settlement held` });
        continue;
      }

      const orderWorkflow =
        orderData?.transaction_type ||
        orderData?.order_type ||
        "self_fulfillment";
      const relevantTerminals =
        terminalByWorkflow.get(orderWorkflow) || allTerminalStatuses;

      const isNonPlatformDelivery =
        orderData?.fulfillment_type === "self_pickup" ||
        orderData?.delivery_handled_by !== "platform";

      if (isNonPlatformDelivery) {
        if (!orderData || !relevantTerminals.has(orderData.status)) {
          errors.push({ id: settlement.id, error: "Order not completed" });
          continue;
        }
      } else {
        const { data: delivery } = await supabase
          .from("delivery_assignments")
          .select("status")
          .eq("order_id", settlement.order_id)
          .single();

        if (delivery?.status !== "delivered") {
          errors.push({ id: settlement.id, error: "Delivery not confirmed" });
          continue;
        }
      }

      const { data: payment } = await supabase
        .from("payment_records")
        .select("payment_status")
        .eq("order_id", settlement.order_id)
        .limit(1)
        .single();

      if (payment?.payment_status !== "paid") {
        errors.push({ id: settlement.id, error: "Payment not confirmed" });
        continue;
      }

      const { error: eligibleErr } = await supabase
        .from("seller_settlements")
        .update({ settlement_status: "eligible" })
        .eq("id", settlement.id);

      if (eligibleErr) {
        errors.push({ id: settlement.id, error: eligibleErr.message });
        continue;
      }

      await supabase.from("audit_log").insert({
        actor_id: null,
        action: "settlement_marked_eligible",
        target_type: "seller_settlements",
        target_id: settlement.id,
        society_id: null,
        metadata: {
          order_id: settlement.order_id,
          seller_id: settlement.seller_id,
          net_amount: settlement.net_amount,
          route_enabled: routeEnabled,
          transfer_attempted: false,
        },
      });

      processed++;
    }

    // 2) When Route enabled: transfer eligible settlements with linked accounts
    if (routeEnabled) {
      if (!creds.keyId || !creds.keySecret) {
        return new Response(
          JSON.stringify({
            processed,
            transferred: 0,
            errors: [
              ...errors,
              {
                id: "route",
                error: "razorpay_route_enabled but credentials missing",
              },
            ],
            route_enabled: true,
            message:
              "Eligible marked where possible; Route transfers skipped — Razorpay credentials missing.",
          }),
          {
            status: 200,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          },
        );
      }

      const { data: eligibleRows, error: eligErr } = await supabase
        .from("seller_settlements")
        .select("id, order_id, seller_id, net_amount, settlement_status, razorpay_transfer_id")
        .eq("settlement_status", "eligible")
        .is("razorpay_transfer_id", null)
        .limit(50);

      if (eligErr) throw eligErr;

      for (const row of eligibleRows || []) {
        const amountPaise = Math.round(Number(row.net_amount || 0) * 100);
        if (!Number.isFinite(amountPaise) || amountPaise <= 0) {
          errors.push({ id: row.id, error: "invalid_net_amount" });
          continue;
        }

        const { data: seller } = await supabase
          .from("seller_profiles")
          .select("id, razorpay_account_id, razorpay_onboarding_status")
          .eq("id", row.seller_id)
          .maybeSingle();

        const accountId = seller?.razorpay_account_id;
        if (!accountId) {
          errors.push({
            id: row.id,
            error: "seller_missing_razorpay_account_id",
          });
          continue;
        }

        // Mark processing before transfer to reduce double-pay races
        const { data: locked, error: lockErr } = await supabase
          .from("seller_settlements")
          .update({
            settlement_status: "processing",
            updated_at: new Date().toISOString(),
          })
          .eq("id", row.id)
          .eq("settlement_status", "eligible")
          .is("razorpay_transfer_id", null)
          .select("id");

        if (lockErr || !locked?.length) {
          errors.push({
            id: row.id,
            error: lockErr?.message || "could_not_lock_for_transfer",
          });
          continue;
        }

        const transfer = await createRouteTransfer({
          keyId: creds.keyId,
          keySecret: creds.keySecret,
          accountId,
          amountPaise,
          settlementId: row.id,
          orderId: row.order_id,
        });

        if (!transfer.ok) {
          await supabase
            .from("seller_settlements")
            .update({
              settlement_status: "eligible",
              hold_reason: `Route transfer failed: ${transfer.error}`,
              updated_at: new Date().toISOString(),
            })
            .eq("id", row.id)
            .eq("settlement_status", "processing");

          errors.push({ id: row.id, error: transfer.error });
          continue;
        }

        const { error: settleErr } = await supabase
          .from("seller_settlements")
          .update({
            settlement_status: "settled",
            razorpay_transfer_id: transfer.transferId,
            hold_reason: null,
            settled_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .eq("id", row.id)
          .eq("settlement_status", "processing");

        if (settleErr) {
          errors.push({
            id: row.id,
            error: `transfer_ok_but_db_update_failed:${settleErr.message}:transfer=${transfer.transferId}`,
          });
          continue;
        }

        await supabase.from("audit_log").insert({
          actor_id: null,
          action: "settlement_route_transferred",
          target_type: "seller_settlements",
          target_id: row.id,
          society_id: null,
          metadata: {
            order_id: row.order_id,
            seller_id: row.seller_id,
            net_amount: row.net_amount,
            razorpay_transfer_id: transfer.transferId,
            account_id: accountId,
          },
        });

        transferred++;
      }
    }

    return new Response(
      JSON.stringify({
        processed,
        transferred,
        errors,
        total_pending: (pendingSettlements || []).length,
        route_enabled: routeEnabled,
        message: routeEnabled
          ? `Marked ${processed} eligible; transferred ${transferred} via Razorpay Route.`
          : "Settlements marked eligible only. Enable razorpay_route_enabled + seller linked accounts for payouts.",
      }),
      {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  } catch (err) {
    return new Response(
      JSON.stringify({ error: (err as Error).message }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

/**
 * Credential resolution order (Phase 0 residual closeout):
 * 1) Deno.env / platform secrets
 * 2) Vault via get_edge_credential RPC (falls back to admin_settings server-side)
 *
 * Never prefer admin_settings SELECT from the edge. Authenticated admin UI must
 * use get_admin_credential_meta (meta-only — no raw secrets).
 */
export async function getCredential(
  supabase: any,
  dbKey: string,
  envKey: string
): Promise<string | undefined> {
  const fromEnv = Deno.env.get(envKey);
  if (fromEnv && fromEnv.trim().length > 0) return fromEnv;

  try {
    const { data, error } = await supabase.rpc("get_edge_credential", {
      p_key: dbKey,
    });
    if (!error && typeof data === "string" && data.trim().length > 0) {
      return data;
    }
    if (error) {
      console.warn(`get_edge_credential failed for ${dbKey}:`, error.message || error);
    }
  } catch (e) {
    console.warn(`get_edge_credential exception for ${dbKey}:`, e);
  }

  return undefined;
}

/** Razorpay key pair — env first, then vault/DB via RPC */
export async function getRazorpayCredentials(supabase: any): Promise<{
  keyId: string;
  keySecret: string;
}> {
  const keyId =
    (await getCredential(supabase, "razorpay_key_id", "RAZORPAY_KEY_ID")) || "";
  const keySecret =
    (await getCredential(supabase, "razorpay_key_secret", "RAZORPAY_KEY_SECRET")) ||
    "";
  return { keyId, keySecret };
}

export async function getRazorpayWebhookSecret(
  supabase: any
): Promise<string | null> {
  const secret = await getCredential(
    supabase,
    "razorpay_webhook_secret",
    "RAZORPAY_WEBHOOK_SECRET"
  );
  return secret && secret.trim().length > 0 ? secret : null;
}

/** Create a service-role Supabase client for credential lookups */
export function createAdminClient() {
  return createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );
}

import { Hono } from "https://deno.land/x/hono@v4.3.11/mod.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";
import { getRazorpayCredentials } from "../_shared/credentials.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const app = new Hono();

// Handle CORS preflight
app.options("*", (c) => {
  return c.json({}, 200, corsHeaders);
});

// Auto-cancel expired urgent orders
app.post("/", async (c) => {
  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    // Security: Only allow invocation via service role key or cron
    const authHeader = c.req.header("Authorization") || "";
    const isServiceRole = authHeader === `Bearer ${supabaseServiceKey}`;
    const isCron = c.req.header("x-cron-secret") === Deno.env.get("CRON_SECRET");
    if (!isServiceRole && !isCron) {
      return c.json({ error: "Unauthorized" }, 401, corsHeaders);
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // --- DB-driven: resolve cancellable statuses from category_status_transitions ---
    // Any status that has a transition TO 'cancelled' (by any actor) is auto-cancellable.
    const { data: cancelTransitions } = await supabase
      .from("category_status_transitions")
      .select("from_status")
      .eq("to_status", "cancelled");

    const dbCancellableStatuses = cancelTransitions
      ? [...new Set(cancelTransitions.map((t: any) => t.from_status))]
      : [];

    // Fallback only if DB returns nothing (e.g. empty transitions table)
    const cancellableStatuses = dbCancellableStatuses.length > 0
      ? dbCancellableStatuses
      : ["placed", "payment_pending"];

    // --- DB-driven: resolve auto-completable statuses from category_status_flows ---
    // Any status flagged as non-terminal that transitions to a terminal+success state
    const { data: completableTransitions } = await supabase
      .from("category_status_transitions")
      .select("from_status")
      .eq("to_status", "completed");

    const dbCompletableStatuses = completableTransitions
      ? [...new Set(completableTransitions.map((t: any) => t.from_status))]
      : [];

    // Load admin overrides from system_settings (optional narrowing)
    const { data: settingsRows } = await supabase
      .from("system_settings")
      .select("key, value")
      .in("key", ["cancellable_statuses_override", "auto_completable_statuses_override"]);

    const settings: Record<string, string> = {};
    for (const row of settingsRows || []) {
      if (row.key && row.value) settings[row.key] = row.value;
    }

    // Admin overrides narrow the DB-derived set (intersection), not replace it
    if (settings["cancellable_statuses_override"]) {
      try {
        const override: string[] = JSON.parse(settings["cancellable_statuses_override"]);
        const overrideSet = new Set(override);
        // Only keep statuses that exist in BOTH the DB transitions and the admin override
        const narrowed = cancellableStatuses.filter(s => overrideSet.has(s));
        if (narrowed.length > 0) cancellableStatuses.splice(0, cancellableStatuses.length, ...narrowed);
      } catch { /* ignore malformed override */ }
    }

    let autoCompletableStatuses = dbCompletableStatuses.length > 0
      ? dbCompletableStatuses
      : ["delivered"];

    // DB-driven grace periods
    const { data: graceRows } = await supabase
      .from("system_settings")
      .select("key, value")
      .in("key", ["auto_cancel_grace_online_seconds", "auto_cancel_grace_urgent_seconds"]);
    const graceMap: Record<string, string> = {};
    for (const r of graceRows || []) if (r.key && r.value) graceMap[r.key] = r.value;
    const onlineGraceSec = parseInt(graceMap["auto_cancel_grace_online_seconds"] || "1800", 10);

    const now = new Date().toISOString();
    const onlineCutoff = new Date(Date.now() - onlineGraceSec * 1000).toISOString();

    // Query 1: Urgent orders past auto_cancel_at (skip if buyer already confirmed/paid)
    const { data: urgentExpired, error: urgentErr } = await supabase
      .from("orders")
      .select("id, buyer_id, seller_id, total_amount, razorpay_order_id, auto_cancel_at, status, payment_status")
      .in("status", cancellableStatuses)
      .not("auto_cancel_at", "is", null)
      .lt("auto_cancel_at", now)
      .not("payment_status", "in", "(buyer_confirmed,paid)");

    // Query 2: Orphaned online orders — payment_status=pending, non-COD, past DB-driven grace
    const { data: orphanedUpi, error: orphanErr } = await supabase
      .from("orders")
      .select("id, buyer_id, seller_id, total_amount, razorpay_order_id, auto_cancel_at, status, payment_status")
      .in("status", cancellableStatuses)
      .eq("payment_status", "pending")
      .neq("payment_type", "cod")
      .lt("created_at", onlineCutoff);

    // Gate: L4 final-warning for SLA / placed cancels ONLY.
    // Unpaid payment orphans (payment TTL) cancel WITHOUT requiring L4.
    // Hard max_defer: if auto_cancel_at is >10 min past, cancel even if L4 missing.
    const MAX_L4_DEFER_MS = 10 * 60 * 1000;
    const { data: l4Rule } = await supabase
      .from("notification_rules")
      .select("id, delay_seconds")
      .eq("key", "order_placed_seller_l4")
      .eq("active", true)
      .maybeSingle();

    // Require the L4 final-warning to have fired AND have aged at least 60s,
    // so we never cancel before the buyer/seller see the final notification.
    const gateCancellation = async (
      candidates: { id: string; auto_cancel_at?: string | null }[],
      opts: { requireL4: boolean },
    ): Promise<Set<string>> => {
      const okIds = new Set<string>();
      if (candidates.length === 0) return okIds;
      if (!opts.requireL4 || !l4Rule) {
        for (const c of candidates) okIds.add(c.id);
        return okIds;
      }

      const ageCutoff = new Date(Date.now() - 60 * 1000).toISOString();
      const { data: tracked } = await supabase
        .from("notification_state_tracker")
        .select("entity_id, last_triggered_at")
        .eq("rule_id", (l4Rule as any).id)
        .in("entity_id", candidates.map((c) => c.id))
        .lte("last_triggered_at", ageCutoff);
      const trackedSet = new Set((tracked || []).map((t: any) => t.entity_id));

      const nowMs = Date.now();
      for (const c of candidates) {
        if (trackedSet.has(c.id)) {
          okIds.add(c.id);
          continue;
        }
        // Hard max_defer after auto_cancel_at even if L4 missing
        if (c.auto_cancel_at) {
          const overdueMs = nowMs - new Date(c.auto_cancel_at).getTime();
          if (overdueMs >= MAX_L4_DEFER_MS) {
            console.log(`[auto-cancel][gate] max_defer override for ${c.id} overdue=${Math.round(overdueMs / 1000)}s`);
            okIds.add(c.id);
          }
        }
      }
      return okIds;
    };

    const fetchError = urgentErr || orphanErr;

    // Tag each order with its cancel reason so we write the correct rejection_reason
    const urgentIds = new Set((urgentExpired || []).map(o => o.id));
    const orphanIds = new Set((orphanedUpi || []).map(o => o.id));

    const isUnpaidTtl = (o: { status?: string; payment_status?: string }) =>
      o.payment_status === "pending" || o.status === "payment_pending";

    // Unpaid TTL (orphans + unpaid urgent): no L4 — cancel releases wallet/loyalty/stock via triggers
    const unpaidUrgent = (urgentExpired || []).filter((o: any) => isUnpaidTtl(o));
    const slaUrgent = (urgentExpired || []).filter((o: any) => !isUnpaidTtl(o));

    const unpaidOk = await gateCancellation(
      [
        ...unpaidUrgent.map((o: any) => ({ id: o.id, auto_cancel_at: o.auto_cancel_at })),
        ...(orphanedUpi || []).map((o: any) => ({ id: o.id, auto_cancel_at: o.auto_cancel_at })),
      ],
      { requireL4: false },
    );
    // Placed/accepted SLA: L4 gate with hard max_defer
    const slaOk = await gateCancellation(
      slaUrgent.map((o: any) => ({ id: o.id, auto_cancel_at: o.auto_cancel_at })),
      { requireL4: true },
    );

    const expiredOrders = [
      ...slaUrgent.filter((o) => slaOk.has(o.id)),
      ...unpaidUrgent.filter((o) => unpaidOk.has(o.id)),
      ...(orphanedUpi || []).filter((o) => unpaidOk.has(o.id)),
    ].filter((order, idx, arr) => arr.findIndex(o => o.id === order.id) === idx);

    const deferredCount =
      new Set([...(urgentExpired || []).map(o => o.id), ...(orphanedUpi || []).map(o => o.id)]).size -
      expiredOrders.length;

    if (fetchError) {
      console.error("Error fetching expired orders:", fetchError);
      return c.json({ error: fetchError.message }, 500, corsHeaders);
    }

    if (deferredCount > 0) {
      console.log(`[auto-cancel][gate] deferring ${deferredCount} SLA orders — L4 final warning not yet fired (unpaid TTL bypasses L4)`);
    }
    if (expiredOrders.length === 0) {
      console.log("No expired orders to cancel");
    } else {
      console.log(`Found ${expiredOrders.length} expired orders to cancel (after gate)`);
    }

    // --- Auto-complete delivered orders past auto_complete_at ---
    const { data: deliveredExpired, error: deliveredErr } = await supabase
      .from("orders")
      .select("id, buyer_id, seller_id")
      .in("status", autoCompletableStatuses)
      .not("auto_complete_at", "is", null)
      .lt("auto_complete_at", now);

    if (deliveredErr) {
      console.error("Error fetching delivered orders for auto-complete:", deliveredErr);
    }

    // --- P0: Buyer Protection SLA — auto-approve refunds after 48h seller inaction ---
    const fortyEightHoursAgo = new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString();
    const { data: slaRefunds, error: slaErr } = await supabase
      .from("refund_requests")
      .select("id, order_id, buyer_id, seller_id, amount")
      .eq("refund_state", "requested")
      .lt("created_at", fortyEightHoursAgo);

    if (slaErr) {
      console.error("Error fetching SLA refunds:", slaErr);
    }

    let slaApprovedCount = 0;
    for (const refund of slaRefunds || []) {
      // Prefer RPC so refund_state + audit stay consistent with money truth path
      const { error: approveErr } = await supabase.rpc("approve_refund", {
        p_refund_id: refund.id,
      });

      if (approveErr) {
        // Fallback: update both legacy status and refund_state together
        const { error: fallbackErr } = await supabase
          .from("refund_requests")
          .update({
            status: "approved",
            refund_state: "approved",
            auto_approved: true,
            approved_at: now,
            notes: "Auto-approved: seller did not respond within 48 hours (Buyer Protection SLA)",
            updated_at: now,
          })
          .eq("id", refund.id)
          .eq("refund_state", "requested");
        if (fallbackErr) {
          console.error(`[SLA] Failed to auto-approve refund ${refund.id}:`, approveErr, fallbackErr);
          continue;
        }
      }

      {
        slaApprovedCount++;
        console.log(`[SLA] Auto-approved refund ${refund.id} for order ${refund.order_id}`);

        // Notify buyer about auto-approval
        await supabase.from("notification_queue").insert({
          user_id: refund.buyer_id,
          title: "Refund Approved",
          body: "Your refund has been automatically approved under our Buyer Protection policy.",
          type: "order",
          reference_path: `/orders/${refund.order_id}`,
          payload: { orderId: refund.order_id, status: "refund_approved", target_role: "buyer" },
        });
      }
    }
    if (slaApprovedCount > 0) {
      console.log(`[SLA] Auto-approved ${slaApprovedCount} refunds under Buyer Protection`);
    }

    // --- P0: Auto-process approved refunds (state machine: approved -> refund_completed) ---
    // Picks up refunds the seller approved (or that were SLA-auto-approved above) and
    // drives them through initiate -> complete via the refund-processor function.
    const { data: approvedRefunds } = await supabase
      .from("refund_requests")
      .select("id")
      .eq("refund_state", "approved")
      .limit(50);

    let processedRefundCount = 0;
    for (const ref of approvedRefunds || []) {
      try {
        const resp = await fetch(`${supabaseUrl}/functions/v1/refund-processor`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${supabaseServiceKey}`,
          },
          body: JSON.stringify({ refund_id: ref.id }),
        });
        if (resp.ok) processedRefundCount++;
        else console.error(`[refund-cron] failed for ${ref.id}: ${resp.status}`);
      } catch (e) {
        console.error(`[refund-cron] error for ${ref.id}`, e);
      }
    }
    if (processedRefundCount > 0) {
      console.log(`[refund-cron] auto-processed ${processedRefundCount} approved refunds`);
    }

    // --- Manual fallback: stuck refunds >72h — VERIFY gateway/wallet before complete ---
    const seventyTwoHoursAgo = new Date(Date.now() - 72 * 60 * 60 * 1000).toISOString();
    const { data: stuckRefunds } = await supabase
      .from("refund_requests")
      .select("id, order_id, gateway_refund_id, refund_destination, amount")
      .in("refund_state", ["refund_initiated", "refund_processing"])
      .lt("processed_at", seventyTwoHoursAgo)
      .limit(50);

    async function verifyRazorpayRefund(gatewayRefundId: string): Promise<"processed" | "pending" | "failed" | "unknown"> {
      try {
        const { keyId, keySecret } = await getRazorpayCredentials(supabase);
        if (!keyId || !keySecret || !gatewayRefundId) return "unknown";

        const res = await fetch(`https://api.razorpay.com/v1/refunds/${gatewayRefundId}`, {
          headers: { Authorization: "Basic " + btoa(`${keyId}:${keySecret}`) },
        });
        if (!res.ok) return "unknown";
        const data = await res.json();
        const st = String(data?.status || "").toLowerCase();
        if (st === "processed") return "processed";
        if (st === "failed") return "failed";
        if (st === "pending" || st === "created") return "pending";
        return "unknown";
      } catch (e) {
        console.warn("[refund-cron] razorpay refund verify failed", e);
        return "unknown";
      }
    }

    for (const ref of stuckRefunds || []) {
      const dest = (ref as any).refund_destination || "original_payment";

      // Wallet path: require ledger proof before complete
      if (dest === "wallet") {
        const { data: walletProof } = await supabase
          .from("wallet_ledger_txns")
          .select("id")
          .eq("reference_type", "refund")
          .eq("reference_id", ref.id)
          .limit(1);
        if (walletProof && walletProof.length > 0) {
          const { error: completeErr } = await supabase.rpc("complete_refund", {
            p_refund_id: ref.id,
            p_gateway_ref: `wallet-verified-${ref.id.slice(0, 8)}`,
            p_gateway_status: "wallet_credited",
          });
          if (completeErr) console.error(`[refund-cron] wallet fallback complete failed`, completeErr);
          else console.log(`[refund-cron] wallet-verified completed refund ${ref.id}`);
        } else {
          const { error: escErr } = await supabase
            .from("refund_requests")
            .update({
              refund_state: "needs_manual_review",
              notes: "needs_manual_review: no wallet ledger proof after 72h",
              updated_at: now,
            })
            .eq("id", ref.id)
            .in("refund_state", ["refund_initiated", "refund_processing"]);
          if (escErr) console.error(`[refund-cron] escalate failed`, escErr);
          else console.warn(`[refund-cron] escalated ${ref.id} to needs_manual_review (no wallet proof)`);
        }
        continue;
      }

      const gatewayRef = (ref as any).gateway_refund_id;
      const rzStatus = await verifyRazorpayRefund(gatewayRef);
      if (rzStatus === "processed") {
        const { error: completeErr } = await supabase.rpc("complete_refund", {
          p_refund_id: ref.id,
          p_gateway_ref: gatewayRef || `rzp-verified-${ref.id.slice(0, 8)}`,
          p_gateway_status: "processed",
        });
        if (completeErr) console.error(`[refund-cron] verified fallback complete failed`, completeErr);
        else console.log(`[refund-cron] razorpay-verified completed refund ${ref.id}`);
      } else {
        // Also accept payment.amount_refunded proof when gateway_refund_id missing/unknown
        let completedViaPayment = false;
        if (rzStatus !== "processed") {
          const { data: orderRow } = await supabase
            .from("orders")
            .select("razorpay_payment_id, checkout_group_id")
            .eq("id", (ref as any).order_id)
            .maybeSingle();
          let paymentId = (orderRow as any)?.razorpay_payment_id || null;
          if (!paymentId && (orderRow as any)?.checkout_group_id) {
            const { data: cg } = await supabase
              .from("checkout_groups")
              .select("razorpay_payment_id")
              .eq("id", (orderRow as any).checkout_group_id)
              .maybeSingle();
            paymentId = (cg as any)?.razorpay_payment_id || null;
          }
          if (paymentId) {
            try {
              const { keyId, keySecret } = await getRazorpayCredentials(supabase);
              if (keyId && keySecret) {
                const payRes = await fetch(`https://api.razorpay.com/v1/payments/${paymentId}`, {
                  headers: { Authorization: "Basic " + btoa(`${keyId}:${keySecret}`) },
                });
                if (payRes.ok) {
                  const pay = await payRes.json();
                  const refundedPaise = Number(pay.amount_refunded || 0);
                  const needPaise = Math.round(Number((ref as any).amount || 0) * 100);
                  if (needPaise > 0 && refundedPaise >= needPaise) {
                    const { error: completeErr } = await supabase.rpc("complete_refund", {
                      p_refund_id: ref.id,
                      p_gateway_ref: `${paymentId}-refunded`,
                      p_gateway_status: "amount_refunded_verified",
                    });
                    if (!completeErr) {
                      completedViaPayment = true;
                      console.log(`[refund-cron] payment-amount verified completed refund ${ref.id}`);
                    }
                  }
                }
              }
            } catch (e) {
              console.warn("[refund-cron] payment amount_refunded check failed", e);
            }
          }
        }
        if (!completedViaPayment) {
          const { error: escErr } = await supabase
            .from("refund_requests")
            .update({
              refund_state: "needs_manual_review",
              notes: `needs_manual_review: razorpay status=${rzStatus} after 72h`,
              updated_at: now,
            })
            .eq("id", ref.id)
            .in("refund_state", ["refund_initiated", "refund_processing"]);
          if (escErr) console.error(`[refund-cron] escalate failed`, escErr);
          else console.warn(`[refund-cron] escalated ${ref.id} to needs_manual_review (rz=${rzStatus})`);
        }
      }
    }

    const thirtyMinDelivered = new Date(Date.now() - 30 * 60 * 1000).toISOString();
    const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString();
    const { data: reviewableOrders, error: reviewErr } = await supabase
      .from("orders")
      .select("id, buyer_id, seller_id, updated_at, seller_profiles!orders_seller_id_fkey(business_name)")
      .eq("status", "delivered")
      .lt("updated_at", thirtyMinDelivered)
      .gt("updated_at", twoHoursAgo); // only process recent deliveries, not ancient ones

    if (reviewErr) {
      console.error("Error fetching reviewable orders:", reviewErr);
    }

    let reviewPromptsCreated = 0;
    for (const order of reviewableOrders || []) {
      // Check if prompt already exists
      const { data: existing } = await supabase
        .from("review_prompts")
        .select("id")
        .eq("order_id", order.id)
        .limit(1);
      if (existing && existing.length > 0) continue;

      const sellerName = (order as any).seller_profiles?.business_name || "the seller";
      const { error: promptErr } = await supabase.from("review_prompts").insert({
        order_id: order.id,
        buyer_id: order.buyer_id,
        seller_id: order.seller_id,
        seller_name: sellerName,
        prompt_at: now,
        status: "pending",
      });
      if (!promptErr) {
        reviewPromptsCreated++;
        // Send notification to buyer
        await supabase.from("notification_queue").insert({
          user_id: order.buyer_id,
          title: `How was your order from ${sellerName}?`,
          body: "Tap to leave a quick review and help your community.",
          type: "order",
          reference_path: `/orders/${order.id}`,
          payload: { orderId: order.id, action: "review_prompt", target_role: "buyer" },
        });
      }
    }
    if (reviewPromptsCreated > 0) {
      console.log(`[ReviewPrompt] Created ${reviewPromptsCreated} review prompts`);
    }

    const autoCompleteResults = await Promise.allSettled(
      (deliveredExpired || []).map(async (order) => {
        const { error: completeError } = await supabase
          .from("orders")
          .update({
            status: "completed",
            auto_complete_at: null,
            updated_at: now,
          })
          .eq("id", order.id)
          .eq("status", "delivered");

        if (completeError) {
          console.error(`Error auto-completing order ${order.id}:`, completeError);
          throw { id: order.id, error: completeError.message };
        }
        console.log(`Order ${order.id} auto-completed`);
        return { id: order.id, success: true };
      })
    );

    // --- Razorpay verification helper: check if payment was actually captured ---
    async function isRazorpayPaid(razorpayOrderId: string): Promise<boolean> {
      try {
        const { keyId, keySecret } = await getRazorpayCredentials(supabase);
        if (!keyId || !keySecret) return false;

        // Fetch payments for this Razorpay order
        const res = await fetch(`https://api.razorpay.com/v1/orders/${razorpayOrderId}/payments`, {
          headers: { Authorization: "Basic " + btoa(`${keyId}:${keySecret}`) },
        });
        if (!res.ok) return false;
        const data = await res.json();
        const items = data.items || data;
        return Array.isArray(items) && items.some((p: any) => p.status === "captured" || p.status === "authorized");
      } catch (e) {
        console.warn("Razorpay verification failed, proceeding with cancel:", e);
        return false;
      }
    }

    // --- Cancel expired orders ---
    // Bug 1 fix: Add status guard to prevent cancelling orders that were accepted between SELECT and UPDATE
    const cancelResults = await Promise.allSettled(
      (expiredOrders || []).map(async (order) => {
        // GUARD: For online orders with a razorpay_order_id, verify with Razorpay before cancelling
        if ((order as any).razorpay_order_id) {
          const actuallyPaid = await isRazorpayPaid((order as any).razorpay_order_id);
          if (actuallyPaid) {
            console.log(`[auto-cancel][reconcile] order=${order.id} razorpay_order_id=${(order as any).razorpay_order_id} result=actually_paid — triggering confirmation`);
            // Trigger the confirm function to fix the state
            try {
              const fnUrl = `${Deno.env.get("SUPABASE_URL")}/functions/v1/confirm-razorpay-payment`;
              await fetch(fnUrl, {
                method: "POST",
                headers: {
                  Authorization: `Bearer ${Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")}`,
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  razorpay_payment_id: "reconciled",
                  razorpay_order_id: (order as any).razorpay_order_id,
                  order_ids: [order.id],
                }),
              });
            } catch (e) {
              console.warn("Reconciliation trigger failed:", e);
            }
            return { id: order.id, success: false, skipped: true, reason: "razorpay_paid" };
          }
        }

        // Dynamic rejection reason based on WHY the order is being cancelled
        const reason = orphanIds.has(order.id) && !urgentIds.has(order.id)
          ? "Order was cancelled as payment was not completed in time"
          : "We couldn't confirm your order as the seller didn't respond in time";

        const { error: updateError, data: updated } = await supabase
          .from("orders")
          .update({
            status: "cancelled",
            rejection_reason: reason,
            auto_cancel_at: null,
            updated_at: now,
          })
          .eq("id", order.id)
          .in("status", cancellableStatuses)
          .select("id");

        if (updateError) {
          console.error(`Error cancelling order ${order.id}:`, updateError);
          throw { id: order.id, error: updateError.message };
        }
        if (!updated || updated.length === 0) {
          console.log(`Order ${order.id} already transitioned — skipping cancel`);
          return { id: order.id, success: false, skipped: true };
        }
        console.log(`[auto-cancel] order=${order.id} result=cancelled reason="${reason}"`);

        // Trigger recovery suggestions for the cancelled buyer
        try {
          const fnUrl = `${Deno.env.get("SUPABASE_URL")}/functions/v1/generate-order-suggestions`;
          await fetch(fnUrl, {
            method: "POST",
            headers: {
              Authorization: `Bearer ${Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ buyer_id: order.buyer_id, cancelled_order_id: order.id }),
          });
          console.log(`[auto-cancel] triggered recovery suggestions for buyer=${order.buyer_id}`);
        } catch (e) {
          console.warn("Failed to trigger order suggestions:", e);
        }

        return { id: order.id, success: true };
      })
    );

    const mapResult = (r: PromiseSettledResult<any>) =>
      r.status === 'fulfilled' ? r.value : { id: (r.reason as any)?.id, success: false, error: (r.reason as any)?.error };

    const cancelledCount = cancelResults.filter(r => r.status === 'fulfilled').length;
    const completedCount = autoCompleteResults.filter(r => r.status === 'fulfilled').length;

    // Trigger push notifications for affected orders
    if (cancelledCount > 0 || completedCount > 0) {
      try {
        const fnUrl = `${supabaseUrl}/functions/v1/process-notification-queue`;
        await fetch(fnUrl, {
          method: "POST",
          headers: {
            Authorization: `Bearer ${supabaseServiceKey}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({}),
        });
        console.log("Triggered process-notification-queue");
      } catch (e) {
        console.warn("Failed to trigger notification queue:", e);
      }
    }

    return c.json(
      {
        message: `Cancelled ${cancelledCount}, auto-completed ${completedCount}, SLA refunds ${slaApprovedCount}, review prompts ${reviewPromptsCreated}`,
        cancelled: cancelledCount,
        auto_completed: completedCount,
        sla_refunds_approved: slaApprovedCount,
        review_prompts_created: reviewPromptsCreated,
        cancel_results: cancelResults.map(mapResult),
        complete_results: autoCompleteResults.map(mapResult),
      },
      200,
      corsHeaders
    );
  } catch (error) {
    console.error("Error in auto-cancel function:", error);
    return c.json({ error: String(error) }, 500, corsHeaders);
  }
});

Deno.serve(app.fetch);

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

/**
 * Credential resolution order (Phase 0 residual closeout):
 * 1) Deno.env / platform secrets
 * 2) Vault via get_edge_credential RPC (falls back to admin_settings server-side)
 *
 * Never prefer admin_settings SELECT from the edge. Authenticated admin UI must
 * use get_admin_credential_meta (meta-only — no raw secrets).
 */
export async function getCredential(
  supabase: any,
  dbKey: string,
  envKey: string
): Promise<string | undefined> {
  const fromEnv = Deno.env.get(envKey);
  if (fromEnv && fromEnv.trim().length > 0) return fromEnv;

  try {
    const { data, error } = await supabase.rpc("get_edge_credential", {
      p_key: dbKey,
    });
    if (!error && typeof data === "string" && data.trim().length > 0) {
      return data;
    }
    if (error) {
      console.warn(`get_edge_credential failed for ${dbKey}:`, error.message || error);
    }
  } catch (e) {
    console.warn(`get_edge_credential exception for ${dbKey}:`, e);
  }

  return undefined;
}

/** Razorpay key pair — env first, then vault/DB via RPC */
export async function getRazorpayCredentials(supabase: any): Promise<{
  keyId: string;
  keySecret: string;
}> {
  const keyId =
    (await getCredential(supabase, "razorpay_key_id", "RAZORPAY_KEY_ID")) || "";
  const keySecret =
    (await getCredential(supabase, "razorpay_key_secret", "RAZORPAY_KEY_SECRET")) ||
    "";
  return { keyId, keySecret };
}

export async function getRazorpayWebhookSecret(
  supabase: any
): Promise<string | null> {
  const secret = await getCredential(
    supabase,
    "razorpay_webhook_secret",
    "RAZORPAY_WEBHOOK_SECRET"
  );
  return secret && secret.trim().length > 0 ? secret : null;
}

/** Create a service-role Supabase client for credential lookups */
export function createAdminClient() {
  return createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );
}
